import {DAY,dayKey,fresh,grade,selectQueue,addRetry,validateBackup,shuffle,seeded,curriculum} from './engine.js';
import {calculationCards,generate,parseNumber,isCorrect} from './calculations.js';
const KEY='finance-remember-v1';
const app=document.querySelector('#app');
let data,cards,byId,state,question,revealed=false,assisted=false,selected=null,numericResult=null,draft='',storageError='',deferredInstall=null,recoveryBlocked=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const date=t=>new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const sourceLink=id=>{const s=data.sources[id]||data.sources.coursera;return `<a href="${esc(s[1])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} ↗</a>`;};
function toast(s){const e=document.querySelector('#toast');e.textContent=s;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',4200);}
function save(){if(recoveryBlocked){toast('Original saved data is protected. Export it in Settings, or import a validated backup.');return;}try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';}catch{storageError='Progress could not be saved on this device. Export a backup before closing.';toast(storageError);}}
function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return fresh();const v=JSON.parse(raw);const checked=validateBackup({app:'finance-remember',version:1,state:v},new Set(cards.map(c=>c.id))).state;
 if(v.settings&&data.topics.some(t=>t.id===v.settings.topic))checked.settings.topic=v.settings.topic;
 if(v.session&&Array.isArray(v.session.queue)&&v.session.queue.every(x=>byId[x])&&Number.isInteger(v.session.index)&&v.session.index>=0&&v.session.index<=v.session.queue.length&&Number.isFinite(v.session.seed)&&v.session.results&&v.session.retries)checked.session=v.session;
 return checked;}catch{recoveryBlocked=true;storageError='Saved progress could not be read. Your stored data has not been overwritten. Settings lets you download the original data.';return fresh();}}
function banner(){return storageError?`<p class="errorbanner" role="alert">${esc(storageError)}</p>`:'';}
function isInstalled(){return window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone===true;}
async function installApp(){
 if(isInstalled()){toast('Remember Finance is already installed on this device.');return;}
 if(deferredInstall){
  const prompt=deferredInstall;deferredInstall=null;
  await prompt.prompt();
  const choice=await prompt.userChoice;
  if(choice?.outcome==='accepted')toast('Remember Finance is ready on your device.');
  return;
 }
 const ua=navigator.userAgent||'',ios=/iPhone|iPad|iPod/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),android=/Android/i.test(ua),safari=/Safari/i.test(ua)&&!/Chrome|CriOS|Edg|OPR|Firefox/i.test(ua);
 const instructions=ios?(safari?'In Safari, tap Share, then choose “Add to Home Screen.” Tap Add to finish.':'Open this page in Safari, tap Share, then choose “Add to Home Screen.” Tap Add to finish.'):
  android?'In Chrome, tap ⋮, then “Install app” or “Add to Home screen.” Confirm the prompt to add it to your device.':
  'In your browser, open its menu and choose “Install Remember Finance” or “Install app.” If that option is unavailable, open this link in Chrome or Edge and try again.';
 document.querySelector('#installInstructions').textContent=instructions;
 const dialog=document.querySelector('#installDialog');
 if(dialog?.showModal)dialog.showModal();else toast(instructions);
}
function topicOptions(value='all'){return `<option value="all" ${value==='all'?'selected':''}>All topics</option>`+data.topics.map(t=>`<option value="${t.id}" ${value===t.id?'selected':''}>${esc(t.title)}</option>`).join('');}
function counts(topic='all'){const a=cards.filter(c=>topic==='all'||c.topic===topic),now=Date.now();return {total:a.length,due:a.filter(c=>state.cards[c.id]?.due<=now).length,seen:a.filter(c=>state.cards[c.id]).length,stable:a.filter(c=>state.cards[c.id]?.stage>=3&&state.cards[c.id].rating!=='again').length};}
function navigate(){question=null;revealed=false;draft='';render();}
function render(){const path=location.hash.slice(1)||'today';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(path.startsWith('topic')?'library':path==='study'?'today':path)));
 if(path==='study'){if(!state.session){location.hash='today';return;}study();}
 else if(path==='library')library();else if(path.startsWith('topic/'))topic(path.split('/')[1]);else if(path==='progress')progress();else if(path==='settings')settings();else today();
}
function today(){const c=counts(),filtered=counts(state.settings.topic),queue=selectQueue(cards,state),day=state.days[dayKey()]||{reviews:0,new:0,correct:0};const resumed=state.session&&state.session.index<state.session.queue.length;
 app.innerHTML=banner()+`<section class="hero"><div><span class="pill">● Your daily learning desk</span><h1>Make finance<br>second nature.</h1><p class="muted">A little recall today. A clearer understanding tomorrow. Revisit Shiller’s Financial Markets one idea at a time.</p><span class="eyebrow">RECALL · SPACING · UNDERSTANDING</span></div><div class="plan"><span class="eyebrow">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</span><h2>${resumed?'Your session is waiting.':queue.length?'A small session. A lasting habit.':'You’re caught up for now.'}</h2><div class="planstats"><div><strong>${filtered.due}</strong><span>reviews due</span></div><div><strong>${resumed?state.session.queue.length-state.session.index:queue.length}</strong><span>in your session</span></div><div><strong>${day.reviews}</strong><span>done today</span></div></div><button class="primary" id="start" ${!resumed&&!queue.length?'disabled':''}>${resumed?'Resume session':queue.length?'Start daily session →':'Nothing due right now'}</button><p class="small muted">About 5–10 minutes · ${state.settings.newLimit} new concepts per day · Save as you go</p></div></section><div class="row wrap"><div><label for="topicfilter">Your focus</label><select id="topicfilter">${topicOptions(state.settings.topic)}</select></div><button id="practice">Extra practice</button></div><section class="sectiontitle"><h2>Your course, at a glance</h2><a class="link small" href="#library">Explore the library →</a></section><div class="grid">${data.topics.map(t=>{const n=counts(t.id);return `<article class="tile"><a href="#topic/${t.id}"><span class="number">${esc(t.title.split(' · ')[0])} / FINANCIAL MARKETS</span><h3>${esc(t.title.split(' · ')[1])}</h3><p class="muted">${esc(t.subtitle)}</p><div class="meter"><span style="width:${n.seen/n.total*100}%"></span></div><div class="row small muted"><span>${n.seen} of ${n.total} explored</span><span>${n.due?`${n.due} due`:'→'}</span></div></a></article>`;}).join('')}</div><div class="sectiontitle"><h2>A better way to remember</h2></div><div class="callout"><p><strong>Try first. Reveal second. Rate your original attempt.</strong></p><p>Say or write the answer before looking. Compare the idea and its limits, then choose Again, Hard, Good or Easy. Missed concepts return after other questions and again tomorrow. Use multiple choice when you need a starting point.</p><p class="sources">${sourceLink('learning')}</p></div>`;
 document.querySelector('#start').onclick=()=>resumed?location.hash='study':start(false);document.querySelector('#practice').onclick=()=>start(true);document.querySelector('#topicfilter').onchange=e=>{state.settings.topic=e.target.value;save();today();};
}
function start(practice=false,topic=state.settings.topic){if(state.session&&state.session.index<state.session.queue.length){location.hash='study';toast('Resuming the session you already started.');return;}
 const queue=selectQueue(cards,state,Date.now(),{topic,practice});if(!queue.length){toast('No cards due here. Try Extra practice or raise the new-concept limit in Settings.');return;}
 state.session={queue,index:0,seed:Math.floor(Math.random()*2**32),results:{},retries:{},practice,topic,started:Date.now()};save();question=null;draft='';revealed=false;location.hash='study';if(location.hash==='#study')render();
}
function makeQuestion(){const s=state.session,c=byId[s.queue[s.index]],visits=s.results[c.id]?.attempts||0;const seed=(s.seed+s.index*769+(state.cards[c.id]?.reviews||0)*1543)>>>0;
 const rng=seeded(seed);return {card:c,seed,calc:c.key?generate(c.key,seed):null,prompt:c.key?null:c.prompts[visits?1:((state.cards[c.id]?.reviews||0)%c.prompts.length)],choices:c.key?[]:shuffle(c.choices,rng)};
}
function study(){const s=state.session;if(s.index>=s.queue.length){complete();return;}if(!question)question=makeQuestion();const c=question.card,t=data.topics.find(t=>t.id===c.topic),calc=question.calc;const choiceMode=state.settings.mode==='choice'||assisted;
 app.innerHTML=banner()+`<div class="study"><div class="studyhead"><div class="row"><a class="back" href="#today">← Save & leave</a><span class="small muted">${s.practice?'Extra practice':'Daily session'} · ${s.index+1} / ${s.queue.length}</span></div><div class="meter"><span style="width:${s.index/s.queue.length*100}%"></span></div></div><article class="studycard"><div class="row wrap"><span class="eyebrow">${esc(t.title.split(' · ')[1])}</span><span class="badge">${calc?'Calculation':choiceMode?'Multiple choice':'Recall first'}</span></div><h2 class="prompt">${esc(calc?calc.prompt:question.prompt)}</h2>${!revealed?calc?`<label for="attempt">Your answer (${esc(calc.unit)})</label><input id="attempt" type="text" inputmode="decimal" autocomplete="off" placeholder="Enter a number" value="${esc(draft)}"><p class="small muted">Use a calculator or scratch paper. ${calc.unit==='percent'?'Enter 6 for 6%, not 0.06.':''} Signed changes can be negative.</p><div class="actions"><button class="primary" id="check">Check answer</button><button id="reveal">Reveal — I don’t know</button></div>`:choiceMode?`<p class="small muted">Choose an answer, then read why. A lucky guess counts as Hard or Again.</p>${question.choices.map((a,i)=>`<button class="choice" data-choice="${i}">${esc(a)}</button>`).join('')}`:`<label for="attempt">Think it through, or write your answer</label><textarea id="attempt" placeholder="Explain it in your own words. What’s the key distinction?">${esc(draft)}</textarea><div class="actions"><button class="primary" id="reveal">Reveal answer</button><button id="choices">Show choices</button></div><p class="small muted">No automatic text grading. You judge your answer after comparing it with the explanation.</p>`:renderAnswer()}
 </article><p class="small muted">Progress is saved on this browser. Your notes and answers are private to this device. <a class="link" href="#settings">Backup & settings</a></p></div>`;
 const attempt=document.querySelector('#attempt');if(attempt){attempt.oninput=e=>draft=e.target.value;if(calc)attempt.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();checkNumber();}};}
 document.querySelector('#reveal')?.addEventListener('click',()=>{revealed=true;if(calc){numericResult=false;assisted=true;}study();focusAnswer();});document.querySelector('#choices')?.addEventListener('click',()=>{assisted=true;study();});document.querySelector('#check')?.addEventListener('click',checkNumber);
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.choice);revealed=true;study();focusAnswer();});document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>rate(b.dataset.rating));
 document.querySelector('#note')?.addEventListener('input',e=>{state.notes[c.id]=e.target.value;save();});
 document.querySelector('#freshnumbers')?.addEventListener('click',()=>{question.seed+=193;question.calc=generate(c.key,question.seed);revealed=false;numericResult=null;assisted=false;draft='';study();});
}
function focusAnswer(){document.querySelector('#answerheading')?.focus({preventScroll:true});}
function checkNumber(){const x=parseNumber(draft);if(x===null){toast('Enter a valid number. A negative sign, commas and $ or % symbols are okay.');return;}numericResult=isCorrect(x,question.calc);revealed=true;study();focusAnswer();}
function renderAnswer(){const {card:c,calc,choices}=question;const correctChoice=selected!==null&&choices[selected]===c.answer;const wrong=calc?numericResult===false:selected!==null&&!correctChoice;const hint=assisted&&!calc;
 const feedback=calc?`<div class="feedback ${numericResult?'':'error'}">${numericResult?'Correct within the rounding tolerance.':draft?`Your answer: ${esc(draft)}. Compare the steps below.`:'No attempt submitted. Study the steps, then revisit it.'}</div>`:selected!==null?`<div class="feedback ${correctChoice?'':'error'}">${correctChoice?'Correct choice. Did you know the reason, or did you guess?':'That choice missed the key distinction.'}</div>`:'';
 const retry=state.session.retries[c.id]||0;
 const explanation=calc?calc.explanation:c.explanation;const answer=calc?calc.answerText:c.answer;
 return `${draft&&!calc?`<details><summary>Your original answer</summary><p style="white-space:pre-wrap">${esc(draft)}</p></details>`:''}${feedback}<section class="answer"><span class="eyebrow">THE KEY IDEA</span><h3 id="answerheading" tabindex="-1">${esc(answer)}</h3><p>${esc(explanation)}</p>${!calc&&c.formula?`<div class="formula">${esc(c.formula)}</div>`:''}<p class="small muted">${wrong?'This concept needs another attempt. Mark Again to bring it back.':hint?'You used a helper. Again or Hard keeps this concept close.':retry?'You are relearning a missed concept. Its next spaced review stays tomorrow.':'Judge your original answer, including the key distinction. Missing a major point counts as Again; needing help or guessing counts as Hard.'}</p>
 <div class="rating"><button class="again" data-rating="again">Again<small>Missed it · retry & tomorrow</small></button><button data-rating="hard" ${wrong?'disabled':''}>Hard<small>Partial / guessed · tomorrow</small></button><button data-rating="good" ${wrong||hint?'disabled':''}>Good<small>Explained it correctly</small></button><button data-rating="easy" ${wrong||hint?'disabled':''}>Easy<small>Clear and confident</small></button></div>
 <details><summary>Read more about this topic</summary>${tParagraphs(data.topics.find(t=>t.id===c.topic).lesson)}</details><details><summary>Your note for this concept</summary><label for="note">Save an example or a point you keep mixing up</label><textarea id="note" maxlength="10000">${esc(state.notes[c.id]||'')}</textarea></details><div class="sources">${sourceLink(c.source)}</div>${calc?'<button class="textbutton" id="freshnumbers">Try another set of numbers before grading</button>':''}</section>`;
}
function rate(rating){const s=state.session,c=question.card;const wrong=question.calc?numericResult===false:selected!==null&&question.choices[selected]!==c.answer;if(wrong)rating='again';if(assisted&&rating!=='again')rating='hard';const now=Date.now(),old=state.cards[c.id],today=dayKey(now),isNew=!old;
 // Extra practice does not postpone an already scheduled spaced review.
 if(!s.practice||isNew||rating==='again'||rating==='hard'){let effective=s.retries[c.id]&&rating!=='again'?'hard':rating;const next=grade(old,effective,now,assisted);if(s.practice&&old)next.due=Math.min(old.due,next.due);state.cards[c.id]=next;}
 const d=state.days[today]||(state.days[today]={reviews:0,new:0,correct:0});d.reviews++;if(isNew)d.new++;if(rating==='good'||rating==='easy')d.correct++;
 const result=s.results[c.id]||(s.results[c.id]={attempts:0,missed:false,last:rating});result.attempts++;result.last=rating;if(rating==='again')result.missed=true;
 if(rating==='again'){s.queue=addRetry(s.queue,c.id,s.index,s.retries);s.retries[c.id]=(s.retries[c.id]||0)+1;}
 s.index++;save();question=null;revealed=false;assisted=false;selected=null;numericResult=null;draft='';study();window.scrollTo({top:0,behavior:'smooth'});
}
function complete(){const s=state.session,entries=Object.entries(s.results),misses=entries.filter(([,r])=>r.missed),now=Date.now();
 app.innerHTML=banner()+`<div class="study center"><div class="bigcheck">✓</div><span class="eyebrow">A LITTLE STRONGER THAN BEFORE</span><h1>Session complete.</h1><p class="muted">You practiced ${entries.length} concepts across ${s.index} attempts.<br>${misses.length?`${misses.length} needed another look. That’s useful information for your next review.`:'Keep the spacing: your next review is scheduled.'}</p><div class="statgrid" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><strong>${entries.length}</strong><span>concepts practiced</span></div><div class="stat"><strong>${misses.length}</strong><span>to strengthen</span></div></div>${misses.length?`<div class="lesson" style="text-align:left"><h3>Ideas to revisit</h3>${misses.map(([id])=>`<p class="small"><a class="link" href="#topic/${byId[id].topic}">${esc(byId[id].title)}</a> · ${state.cards[id]?date(state.cards[id].due):'next session'}</p>`).join('')}</div>`:''}<div class="actions"><button class="primary" id="finish">Back to today</button><button id="more">Extra practice</button></div><p class="small muted">A short break is part of learning. The scheduler uses a simple, transparent spacing rule; it does not claim to predict your memory exactly.</p></div>`;
 document.querySelector('#finish').onclick=()=>{state.session=null;save();location.hash='today';};document.querySelector('#more').onclick=()=>{state.session=null;save();start(true);};
}
function tParagraphs(text){return text.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('');}
function library(){app.innerHTML=banner()+`<span class="eyebrow">YOUR REFERENCE SHELF</span><h1>Connect the ideas.</h1><p class="muted">${data.cards.length} concept cards and ${calculationCards().length} calculation templates. Search for a term, read a short explanation, or practice a topic.</p><div class="search"><input type="search" id="search" placeholder="Search yield, mortgage, beta…" aria-label="Search the library"><select id="librarytopic" aria-label="Filter library by topic">${topicOptions()}</select></div><div id="matches"></div>`;
 const update=()=>{const term=document.querySelector('#search').value.toLowerCase(),t=document.querySelector('#librarytopic').value;const found=cards.filter(c=>(t==='all'||c.topic===t)&&[c.title,c.answer,c.explanation,c.formula,data.topics.find(t=>t.id===c.topic).title].join(' ').toLowerCase().includes(term));
 document.querySelector('#matches').innerHTML=`<p class="small muted">${found.length} results</p>`+found.map(c=>`<details class="librarycard"><summary>${esc(c.title)} <span class="badge">${c.key?'Numbers vary':'Concept'}</span></summary><p class="meta">${esc(data.topics.find(t=>t.id===c.topic).title)} · ${state.cards[c.id]?'Next review '+date(state.cards[c.id].due):'Not introduced yet'}</p>${c.key?`<p>${esc(generate(c.key,123).prompt)}</p><div class="formula">${esc(generate(c.key,123).explanation)}</div>`:`<h3>${esc(c.answer)}</h3><p>${esc(c.explanation)}</p>${c.formula?`<div class="formula">${esc(c.formula)}</div>`:''}`}<p class="sources">${sourceLink(c.source)}</p><a class="link small" href="#topic/${c.topic}">Read topic & practice →</a></details>`).join('');};
 document.querySelector('#search').oninput=update;document.querySelector('#librarytopic').onchange=update;update();
}
function topic(id){const t=data.topics.find(t=>t.id===id);if(!t){location.hash='library';return;}const n=counts(id);app.innerHTML=banner()+`<a class="back" href="#library">← Library</a><br><span class="eyebrow">${esc(t.subtitle)}</span><h1>${esc(t.title.split(' · ')[1])}</h1><div class="row wrap"><span class="small muted">${n.total} concepts & calculation templates · ${n.seen} explored · ${n.due} due</span><button class="primary" id="topicpractice">Practice this topic →</button></div><article class="lesson">${tParagraphs(t.lesson)}</article><div class="sectiontitle"><h2>The ideas to retain</h2></div>${cards.filter(c=>c.topic===id).map(c=>`<details class="librarycard"><summary>${esc(c.title)}</summary>${c.key?`<p>${esc(generate(c.key,321).prompt)}</p><div class="formula">${esc(generate(c.key,321).explanation)}</div>`:`<p><strong>${esc(c.answer)}</strong></p><p>${esc(c.explanation)}</p>${c.formula?`<div class="formula">${esc(c.formula)}</div>`:''}`}<p class="sources">${sourceLink(c.source)}</p></details>`).join('')}`;document.querySelector('#topicpractice').onclick=()=>start(true,id);}
function progress(){const c=counts(),days=Object.entries(state.days),attempts=days.reduce((n,[,d])=>n+d.reviews,0);const recent=Array.from({length:14},(_,i)=>dayKey(Date.now()-(13-i)*DAY));
 app.innerHTML=banner()+`<span class="eyebrow">SEE WHAT’S TAKING ROOT</span><h1>Your understanding,<br>over time.</h1><p class="muted">Explored means you have attempted a concept. Spaced means its interval reached at least 14 days; it is a scheduling indicator, not proof of mastery.</p><div class="statgrid"><div class="stat"><strong>${c.seen}/${c.total}</strong><span>concepts explored</span></div><div class="stat"><strong>${c.stable}</strong><span>at 14+ day spacing</span></div><div class="stat"><strong>${c.due}</strong><span>due now</span></div><div class="stat"><strong>${attempts}</strong><span>total attempts</span></div></div><div class="sectiontitle"><h2>The last two weeks</h2></div><div class="activity">${recent.map(d=>`<div class="day ${state.days[d]?.reviews?'used':''}" title="${d}"><strong>${state.days[d]?.reviews||0}</strong>${d.slice(5)}</div>`).join('')}</div><div class="sectiontitle"><h2>Topic coverage</h2></div><div class="bars">${data.topics.map(t=>{const n=counts(t.id);return `<div class="bar"><a class="link" href="#topic/${t.id}">${esc(t.title.split(' · ')[1])}</a><div class="meter"><span style="width:${n.seen/n.total*100}%"></span></div><span>${n.seen}/${n.total}</span></div>`;}).join('')}</div><div class="sectiontitle"><h2>Needs another look</h2></div>${cards.filter(c=>state.cards[c.id]?.rating==='again'||state.cards[c.id]?.rating==='hard').sort((a,b)=>(state.cards[b.id].lapses||0)-(state.cards[a.id].lapses||0)).slice(0,10).map(c=>`<p class="small"><a class="link" href="#topic/${c.topic}">${esc(c.title)}</a> · next ${date(state.cards[c.id].due)}</p>`).join('')||'<p class="muted">Your practice will show where to focus.</p>'}`;
}
function settings(){app.innerHTML=banner()+`<span class="eyebrow">MAKE IT A SUSTAINABLE HABIT</span><h1>Your pace. Your data.</h1><div class="settingsgrid"><section class="tile"><h3>Daily rhythm</h3><div class="setting"><label for="limit">Session size (before missed-card retries)</label><select id="limit">${[6,12,20].map(n=>`<option ${state.settings.limit===n?'selected':''} value="${n}">${n} questions</option>`).join('')}</select></div><div class="setting"><label for="newlimit">Maximum new concepts per day</label><select id="newlimit">${[0,2,4,8].map(n=>`<option ${state.settings.newLimit===n?'selected':''} value="${n}">${n}${n===0?' · reviews only':''}</option>`).join('')}</select></div><div class="setting"><label for="mode">Default practice style</label><select id="mode"><option value="recall" ${state.settings.mode==='recall'?'selected':''}>Recall first · recommended</option><option value="choice" ${state.settings.mode==='choice'?'selected':''}>Multiple choice</option></select></div><p class="small muted">Calculations use numeric answers in either mode. Extra practice can exceed the daily introduction limit and does not postpone existing due dates.</p><button id="install">Install on your phone</button></section><section class="tile"><h3>Progress backup</h3><p class="small muted">Reviews and notes live in this browser. There is no account sync. Export regularly, and import the file on another device to move progress.</p><div class="actions"><button class="primary" id="export">Export backup</button><button id="import">Import backup</button></div><input id="importfile" type="file" accept="application/json,.json" class="hidden"><div id="importpreview"></div><button class="textbutton" id="rawbackup">Download original stored data</button></section><section class="tile"><h3>How reviews work</h3><p class="small">Correct recall moves through approximately 1, 3, 7, 14, 30, 60 and 120 days. Easy advances faster. Hard stays close; Again returns later in the session, at most twice, then tomorrow. Relearning never counts as long-term mastery.</p><p class="small muted">The intervals are practical defaults, not a validated personal memory model. Try 5–10 minutes daily. Explain one concept aloud and work one calculation without copying its steps.</p><p class="sources">${sourceLink('learning')}</p></section><section class="tile"><h3>Content & sources</h3><p class="small">This is an independently written study companion to Shiller’s introductory Financial Markets course. The Coursera syllabus informed coverage. Added mathematics and modern context fill useful gaps. It is not affiliated with Yale or a reproduction of course quizzes.</p><p class="small muted">Dated updates checked October 11, 2026. This snapshot does not refresh automatically. History is used to explain mechanisms; current proposals and effective rules are distinguished in their cards.</p><div class="sources">${Object.keys(data.sources).filter(k=>k!=='learning').map(k=>`<p>${sourceLink(k)}</p>`).join('')}</div></section></div>`;
 for(const [id,key] of [['limit','limit'],['newlimit','newLimit'],['mode','mode']])document.querySelector('#'+id).onchange=e=>{state.settings[key]=key==='mode'?e.target.value:Number(e.target.value);save();toast('Preference saved.');};
 document.querySelector('#export').onclick=()=>download(JSON.stringify({app:'finance-remember',version:1,exported:new Date().toISOString(),state},null,2),'finance-progress-'+dayKey()+'.json');
 document.querySelector('#rawbackup').onclick=()=>{try{download(localStorage.getItem(KEY)||'{}','finance-original-data.json');}catch{toast('This browser is blocking storage access.');}};
 document.querySelector('#import').onclick=()=>document.querySelector('#importfile').click();document.querySelector('#importfile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('Backup is too large.');const imported=validateBackup(JSON.parse(await file.text()),new Set(cards.map(c=>c.id)));const preview=document.querySelector('#importpreview');preview.innerHTML=`<p class="small">Valid backup: ${imported.imported} review records. Importing replaces this browser’s finance progress and ends its current session.</p><button id="confirmimport">Replace progress with this backup</button><button id="cancelimport">Cancel</button>`;document.querySelector('#cancelimport').onclick=()=>preview.innerHTML='';document.querySelector('#confirmimport').onclick=()=>{state=imported.state;recoveryBlocked=false;save();settings();toast('Progress imported.');};}catch(err){toast(err.message||'Could not read backup.');}};
 document.querySelector('#install').onclick=installApp;
}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.addEventListener('hashchange',navigate);document.querySelector('#installApp').addEventListener('click',installApp);document.querySelector('#closeInstall').addEventListener('click',()=>document.querySelector('#installDialog').close());window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});window.addEventListener('appinstalled',()=>{deferredInstall=null;document.querySelector('#installApp').hidden=true;toast('Remember Finance is installed.');});if(isInstalled())document.querySelector('#installApp').hidden=true;
try{const res=await fetch('content.json');if(!res.ok)throw Error('Content could not load.');data=await res.json();cards=curriculum(data.cards,calculationCards());byId=Object.fromEntries(cards.map(c=>[c.id,c]));state=load();render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(err){app.innerHTML=`<p class="errorbanner">${esc(err.message)} Reload when you have a connection.</p>`;}
